import{_ as a}from"./chunks/popup-translate.CYMtVXLB.js";import{_ as e,o,c as r,a2 as l}from"./chunks/framework.CfwCq2QB.js";const d="/dev-go-docs/shots/0.2.3/zh-CN/light/options-translate.png",b=JSON.parse('{"title":"整页双语翻译","description":"","frontmatter":{},"headers":[],"relativePath":"features/page-translate.md","filePath":"features/page-translate.md"}'),i={name:"features/page-translate.md"};function s(n,t,h,c,p,g){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="整页双语翻译" tabindex="-1">整页双语翻译 <a class="header-anchor" href="#整页双语翻译" aria-label="Permalink to &quot;整页双语翻译&quot;">​</a></h1><p>一句话：译文插在原文段落之后，随滚动按需翻译，再点一次还原；支持 Shadow DOM / Web Components 页面。</p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><ul><li><strong>弹窗</strong>：<code>Alt+1</code> →「翻译」页 →「翻译当前页面 / 显示原文」</li><li><strong>右键菜单</strong>：页面空白处右键 →「翻译当前页面（再次点击恢复原文）」</li><li><strong>悬浮快捷栏</strong>：悬停网页右侧悬浮条 →「翻译本页 / 显示原文」</li><li><strong>快捷键</strong>：「整页行间翻译」默认未绑定，可在 <code>chrome://extensions/shortcuts</code> 自行设置</li><li><strong>自动</strong>：把常用站点加进「总是翻译的网站」，打开即自动翻译</li></ul><img src="'+a+'" alt="弹窗翻译页" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：弹窗「翻译」页——引擎、目标语言与「总是翻译该网站」。</em></p><h2 id="翻译引擎" tabindex="-1">翻译引擎 <a class="header-anchor" href="#翻译引擎" aria-label="Permalink to &quot;翻译引擎&quot;">​</a></h2><table tabindex="0"><thead><tr><th>引擎</th><th>特点</th></tr></thead><tbody><tr><td>微软 · 免翻墙</td><td>默认。免费可用，国内网络直连</td></tr><tr><td>Google</td><td>翻译质量好，需要代理</td></tr><tr><td>AI 大模型</td><td>用你自己的模型翻译，质量与术语可控；需在<a href="/dev-go-docs/settings/models.html">AI 模型</a>配置翻译模型</td></tr></tbody></table><p>目标语言默认「自动」：中文页面译成英文，其余页面译成简体中文；也可以固定为 17 种语言中的任意一种。</p><h2 id="展示方式" tabindex="-1">展示方式 <a class="header-anchor" href="#展示方式" aria-label="Permalink to &quot;展示方式&quot;">​</a></h2><p>在设置页「翻译 → 网页翻译」里可调：</p><ul><li><strong>双语对照</strong>（默认）：译文插在原文段落之后</li><li><strong>仅译文</strong>：隐藏原文，只保留译文，读起来更沉浸</li><li><strong>译文下划线</strong>：给译文加虚线，方便和原文区分</li></ul><h2 id="悬停翻译" tabindex="-1">悬停翻译 <a class="header-anchor" href="#悬停翻译" aria-label="Permalink to &quot;悬停翻译&quot;">​</a></h2><p>不想整页翻？设置页「翻译」里可以开启<strong>悬停翻译</strong>，只翻鼠标下的段落：</p><table tabindex="0"><thead><tr><th>模式</th><th>用法</th></tr></thead><tbody><tr><td>按 <code>Alt</code> / <code>Ctrl</code> / <code>Shift</code></td><td>鼠标指向段落，按一下修饰键翻译，再按一次恢复（默认 Alt，macOS 为 ⌥）</td></tr><tr><td>停留自动翻译</td><td>鼠标在段落上停留片刻自动翻译</td></tr></tbody></table><h2 id="总是翻译的网站" tabindex="-1">总是翻译的网站 <a class="header-anchor" href="#总是翻译的网站" aria-label="Permalink to &quot;总是翻译的网站&quot;">​</a></h2><p>把 <code>developer.mozilla.org</code> 这类常读的外文站加进列表，打开就自动整页翻译。也可以在弹窗「翻译」页对当前网站一键开关。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>浏览器内置页（<code>chrome://</code> 开头）和扩展商店不支持翻译；普通网页如果刚装扩展就翻不了，刷新一次再试</li><li>长页面按需加载：滚动到哪翻到哪，失败段落后面有 ↻ 可以单独重试</li><li>选 AI 大模型翻译时，建议选不带深度思考的快模型（如 glm-5.3-flash、qwen-turbo），整页翻译更跟手</li></ul><img src="'+d+'" alt="翻译设置"><p><em>图：设置页「翻译」——展示方式、译文下划线、悬停翻译与总是翻译的网站。</em></p>',21)])])}const _=e(i,[["render",s]]);export{b as __pageData,_ as default};
